contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract: deposit some Ether into c, then call withdrawAll as owner
    // params: ownerCaller must be the owner address stored in c, recipient is arbitrary, amount is positive
    function run(address ownerCaller, address payable recipient, uint256 amount) external payable {
        // preconditions
        require(address(this).balance >= amount);
        require(ownerCaller != address(0));
        require(recipient != address(0));

        // fund the contract c by sending Ether to its fallback
        // send as this contract
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        // ensure msg.sender for withdrawAll is the owner: we simulate by requiring ownerCaller equals c.owner()
        // read owner from c
        address actualOwner = c.owner();
        require(ownerCaller == actualOwner);

        // perform withdrawAll as ownerCaller by calling through this contract (msg.sender will be this contract)
        // To make msg.sender equal owner, we require that this contract's address equals ownerCaller.
        // So require that ownerCaller == address(this)
        require(ownerCaller == address(this));

        // now call withdrawAll providing recipient
        c.withdrawAll(recipient);

        // After withdrawAll, the recipient must have received the full amount (i.e., contract c balance is zero and recipient balance increased)
        // We can observe c's balance and this contract's balance; we also know the recipient's balance before and after via address().balance
        // But we cannot read prior balance now; instead require that c balance is zero and address(c).balance == 0
        assert(address(c).balance == 0);
    }

    // allow this test contract to receive Ether so it can be owner and fund c
    receive() external payable {}
}

