        // sanity: c had balance equal to fundAmount
        assert(address(c).balance == fundAmount);

        // owner (this) calls withdrawAll with the adversarial recipient that reverts on transfer
        // For the reference contract, the transfer is to provided recipient and will revert -> withdrawAll will revert
        // But the reference uses transfer to recipient; since recipient reverts, the call will revert and no balance change.
        // However our general property is: when owner successfully calls withdrawAll(recipient) (i.e., call does not revert), c.balance must be zero.
        // The mutant that always sends to owner can succeed for this recipient (owner is payable) and leave c.balance zero as well,
        // but the distinguishing case is when recipient accepts but owner refusing would differ; to produce a case that reference passes and mutant fails,
        // instead we observe the post-call balance when the call succeeds. We ensure the call is made to a recipient that DOES accept funds (an EOA)
        // to exercise the success path. Use a fuzzed recipient by deriving an address from the provided bytes32 (deterministic but not hard-coded).

        // derive a recipient EOA from the fuzzed bytes32 by turning it into an address with no code
        address recipient = address(uint160(uint256(keccak256(abi.encodePacked(bytes32("fixed"), block.timestamp)))));
        // ensure recipient has no code (EOA) by making sure it is not a contract
        vm.assume(recipient.code.length == 0);

        // fund the contract again to ensure it has funds for withdrawing to this recipient
        // first, refill c to fundAmount
        (bool sent2,) = address(c).call{value: fundAmount}("");
        require(sent2, "refunding failed");
        assert(address(c).balance == fundAmount);

        // have owner (this) call withdrawAll(recipient)
